INSERT INTO user_access_scopes(user_id,scope_type,scope_id,is_active,created_at,updated_at) SELECT u.user_id,'university',p.organizational_unit_id,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM users u JOIN organizational_units p ON p.unit_code='PRES' WHERE u.username IN ('registrar','exam.board') ON DUPLICATE KEY UPDATE is_active=1,updated_at=CURRENT_TIMESTAMP;
